using HRIS.Api.Common; using HRIS.Api.Data; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Models.Enums; using Microsoft.EntityFrameworkCore;
namespace HRIS.Api.Services; public class LaptopApprovalHandler:IApprovalHandler { private readonly AppDbContext _db; public LaptopApprovalHandler(AppDbContext db)=>_db=db; public string RequestType=>ApprovalRequestTypes.Laptop; public async Task OnCompletedAsync(ApprovalRequest request,ApprovalRequestStatus finalStatus){var x=await _db.LaptopRequests.FindAsync(request.RequestRefId)??throw new NotFoundException("Permintaan laptop tidak ditemukan."); if(finalStatus==ApprovalRequestStatus.Approved && x.Status!="ForwardedToIT") throw new BadRequestException("Permintaan laptop harus berstatus ForwardedToIT sebelum approval HR."); x.Status=finalStatus switch{ApprovalRequestStatus.Approved=>"Approved",ApprovalRequestStatus.Rejected=>"Rejected",ApprovalRequestStatus.Cancelled=>"Cancelled",_=>x.Status}; if(finalStatus!=ApprovalRequestStatus.Cancelled){var step=request.Steps.FirstOrDefault(s=>s.Level==request.CurrentLevel);_db.LaptopStatusLogs.Add(new LaptopStatusLog{LaptopId=x.Id,Status=x.Status,ChangedBy=step?.ActedByUserId??request.RequesterId,ChangedAt=DateTime.UtcNow,Note=$"Approval selesai: {finalStatus}"});} await _db.SaveChangesAsync();} }
